import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;

import 'package:aggregate/features/settings/theme_switch_simulation.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test(
    'matches independent source-model samples through interrupted motion',
    () {
      // The fixture was sampled from the author's JavaScript, not generated by
      // ThemeSwitchSimulation. Its provenance records the URL, SHA256, seeded
      // random generator and input events so an oracle update can be audited.
      final fixture = jsonDecode(
        File('test/fixtures/theme_switch_model.json').readAsStringSync(),
      ) as Map<String, dynamic>;
      final provenance = fixture['provenance'] as Map<String, dynamic>;
      final simulation = ThemeSwitchSimulation(seed: provenance['seed'] as int);
      final fps = (provenance['frames_per_second'] as num).toDouble();
      final expected = <int, Map<String, dynamic>>{
        for (final row in fixture['frames'] as List)
          (row as Map<String, dynamic>)['i'] as int: row,
      };
      final events = <int, Map<String, dynamic>>{
        for (final row in provenance['events_before_frame'] as List)
          (row as Map<String, dynamic>)['frame'] as int: row,
      };
      final particleIndices = (fixture['particle_indices'] as List).cast<int>();
      final lastFrame = expected.keys.reduce(math.max);

      for (var frame = 0; frame <= lastFrame; frame++) {
        final event = events[frame];
        if (event?.containsKey('hover') ?? false) {
          simulation.setHovered(event!['hover'] as bool);
        }
        if (event?.containsKey('light') ?? false) {
          simulation.setLight(event!['light'] as bool);
        }
        simulation.advance(frame == 0 ? 0 : 1 / fps, frame / fps);

        final sample = expected[frame];
        if (sample == null) continue;
        final snapshot = simulation.snapshot;
        final scalars = {
          'p': snapshot.position,
          'v': snapshot.velocity,
          'theme': snapshot.theme,
          'x': snapshot.knobX,
          'hx': snapshot.halfWidth,
          'hy': snapshot.halfHeight,
          'theta': snapshot.theta,
          'led': snapshot.led,
          'lift': snapshot.lift,
        };
        for (final scalar in scalars.entries) {
          expect(
            scalar.value,
            closeTo((sample[scalar.key] as num).toDouble(), 1e-9),
            reason: 'source frame $frame, ${scalar.key}',
          );
        }
        expect(snapshot.particles.length, provenance['particle_count']);
        final particles = sample['particles'] as Map<String, dynamic>;
        for (final index in particleIndices) {
          final particle = snapshot.particles[index];
          final actual = [
            particle.x,
            particle.y,
            particle.size,
            particle.alpha,
          ];
          final expectedParticle = particles['$index'] as List;
          for (var field = 0; field < actual.length; field++) {
            expect(
              actual[field],
              closeTo((expectedParticle[field] as num).toDouble(), 1e-9),
              reason: 'source frame $frame, particle $index, field $field',
            );
          }
        }
      }
    },
  );

  test(
    'snap discards momentum and establishes the requested settled endpoint',
    () {
      final simulation = ThemeSwitchSimulation()..setLight(true);
      for (var frame = 1; frame <= 10; frame++) {
        simulation.advance(1 / 60, frame / 60);
      }
      expect(simulation.velocity.abs(), greaterThan(0));

      for (final light in [false, true]) {
        simulation.snapTo(light);
        final snapshot = simulation.snapshot;
        expect(simulation.light, light);
        expect(snapshot.position, light ? 1 : 0);
        expect(snapshot.velocity, 0);
        expect(snapshot.theme, light ? 1 : 0);
        expect(snapshot.knobX, light ? 104 : -104);
        expect(snapshot.halfWidth, 99);
        expect(snapshot.halfHeight, 99);
        expect(snapshot.theta, light ? -math.pi / 2 : math.pi / 2);
        expect(snapshot.led, 1.89);

        simulation.advance(1 / 60, 11 / 60);
        final after = simulation.snapshot;
        expect(after.position, snapshot.position);
        expect(after.velocity, 0);
        for (var i = 0; i < after.particles.length; i++) {
          expect(after.particles[i].x, snapshot.particles[i].x);
          expect(after.particles[i].y, snapshot.particles[i].y);
        }
      }
    },
  );

  test(
    'changing destination preserves current position and particle motion',
    () {
      final simulation = ThemeSwitchSimulation()..setLight(true);
      for (var frame = 1; frame <= 8; frame++) {
        simulation.advance(1 / 60, frame / 60);
      }
      final before = simulation.snapshot;
      expect(before.position, inExclusiveRange(0, 1));
      expect(before.velocity, greaterThan(0));

      simulation.setLight(false);
      final after = simulation.snapshot;
      expect(simulation.light, isFalse);
      expect(after.position, before.position);
      expect(after.velocity, before.velocity);
      _expectSameParticles(after, before);

      for (var frame = 9; frame <= 150; frame++) {
        simulation.advance(1 / 60, frame / 60);
      }
      expect(simulation.position, closeTo(0, 1e-6));
    },
  );

  test(
    'drag reversal and cancellation retain presentation and original target',
    () {
      final simulation = ThemeSwitchSimulation();
      simulation.dragTo(0.7, 2);
      simulation.advance(1 / 60, 1 / 60);
      simulation.dragTo(0.35, -3);
      final beforeCancel = simulation.snapshot;
      expect(beforeCancel.position, 0.35);
      expect(beforeCancel.velocity, closeTo(-0.72, 1e-12));

      simulation.releaseDrag(cancel: true);
      final afterCancel = simulation.snapshot;
      expect(simulation.light, isFalse);
      expect(afterCancel.position, beforeCancel.position);
      expect(afterCancel.velocity, beforeCancel.velocity);
      _expectSameParticles(afterCancel, beforeCancel);

      simulation.advance(1 / 60, 2 / 60);
      expect(simulation.position, lessThan(beforeCancel.position));
      expect(simulation.position, greaterThan(0));
    },
  );

  test(
    'pointer capture freezes travel and measures elastic boundary velocity',
    () {
      final simulation = ThemeSwitchSimulation()
        ..setPresentation(position: 0.9, velocity: 2);
      simulation.beginDrag();
      simulation.advance(1 / 60, 1 / 60);
      expect(simulation.position, 0.9);
      expect(simulation.velocity, 2);

      simulation.dragTo(1.1, 0, elapsedSeconds: 0.1);
      expect(simulation.position, closeTo(1.022, 1e-12));
      // The first interval crosses 1.0: only the portion beyond it is resisted.
      // ((1.022 - 0.9) / 0.1) * 0.4 = 0.488.
      expect(simulation.velocity, closeTo(0.488, 1e-12));
      simulation.dragTo(1.2, 0, elapsedSeconds: 0.1);
      expect(simulation.position, closeTo(1.044, 1e-12));
      expect(simulation.velocity, closeTo(0.3808, 1e-12));
    },
  );
}

void _expectSameParticles(
  ThemeSwitchSnapshot actual,
  ThemeSwitchSnapshot before,
) {
  expect(actual.particles.length, before.particles.length);
  for (var i = 0; i < actual.particles.length; i++) {
    expect(actual.particles[i].x, before.particles[i].x);
    expect(actual.particles[i].y, before.particles[i].y);
    expect(actual.particles[i].size, before.particles[i].size);
    expect(actual.particles[i].alpha, before.particles[i].alpha);
  }
}
